def observe_probe_flow(self, trade_ticks: Dict[str, Any]) -> None:
    # One observed poll batch, not one observation per print. Key by the
    # resting side consumed; sell aggressors remove bid depth and vice versa.
    for inst_id, prints in trade_ticks.items():
        totals = {'bid': 0, 'ask': 0}
        for tr in prints or ():
            aggressor = str(getattr(tr, 'aggressor_side', '')).strip().lower()
            if aggressor not in ('ask', 'bid'):
                continue
            resting = 'bid' if aggressor == 'ask' else 'ask'
            totals[resting] += max(0, int(getattr(tr, 'volume', 0) or 0))
        for side, qty in totals.items():
            if not qty:
                continue
            key = (inst_id, side)
            if key not in self._sweep_batches:
                self._sweep_batches[key] = deque(maxlen=32)
            window = self._sweep_batches[key]
            window.append(qty)
            self._sweep_p90[key] = sorted(window)[math.ceil(0.90 * len(window)) - 1]

def _backed_probe(self, inst_id: str, side: str, entry: float, tick: float, levels: Any) -> int:
    exit_px = entry - tick if side == 'bid' else entry + tick
    depth = volume_at_price(levels, exit_px, tick)
    # Even at cold start require room for external flow plus the exit lot.
    stress = self._sweep_p90.get((inst_id, side), 1)
    return int(depth >= stress + 1)

